def find(name, top):
    for root, _, files in os.walk(top):
        if 'backup' in root:
            continue
        if name in files:
            return os.path.join(root, name)
    return None

def load(p):
    raw = open(p, 'rb').read().decode('utf-8')
    return raw.replace('\r\n', '\n'), ('\r\n' in raw)

if not os.path.isdir('lib') or not os.path.isdir('android'):
    print('❌ 프로젝트 폴더(mp3_player_new)에서 실행해 주세요'); sys.exit(1)
tp = find('theme_provider.dart', os.path.join('lib', 'providers'))
ss = find('settings_screen.dart', os.path.join('lib', 'screens'))
rk = find('radio_korea_screen2.dart', os.path.join('lib', 'screens'))
pub = 'pubspec.yaml'
for n, p in (('theme_provider.dart', tp), ('settings_screen.dart', ss), ('radio_korea_screen2.dart', rk), ('pubspec.yaml', pub)):
    if not p or not os.path.isfile(p):
        print('❌ %s 를 못 찾았어요' % n); sys.exit(1)
t = open(tp, encoding='utf-8').read()
if 'textSteps' not in t:
    print('❌ apply_fonts2.py 를 먼저 해 주세요'); sys.exit(1)
if "'line_seed'" in t:
    print('이미 적용돼 있어요'); sys.exit(0)

writes = {}
ok = True
def edit(path, pairs):
    global ok
    src, crlf = writes[path] if path in writes else load(path)
    for label, old, new in pairs:
        n = src.count(old)
        if n != 1:
            print('❌ %s (찾은 개수 %d)' % (label, n)); ok = False; continue
        src = src.replace(old, new)
        print('✔ %s' % label)
    writes[path] = (src, crlf)

edit(pub, [
    ('pubspec: 라인 시드 등록',
     '        - asset: assets/fonts/SpoqaHanSansNeo-Bold.ttf\n'
     '          weight: 700\n',
     '        - asset: assets/fonts/SpoqaHanSansNeo-Bold.ttf\n'
     '          weight: 700\n'
     '    - family: LINESeedKR\n'
     '      fonts:\n'
     '        - asset: assets/fonts/LINESeedKR-Regular.otf\n'
     '        - asset: assets/fonts/LINESeedKR-Bold.otf\n'
     '          weight: 700\n'),
])
edit(tp, [
    ('테마: 글꼴 목록에 라인 시드',
     "    {'key': 'pretendard', 'name': 'Pretendard'},\n",
     "    {'key': 'pretendard', 'name': 'Pretendard'},\n"
     "    {'key': 'line_seed', 'name': 'LINESeedKR'},\n"),
    ('테마: 앱 안 글꼴 이름',
     "      'pretendard': 'Pretendard',\n",
     "      'pretendard': 'Pretendard',\n"
     "      'line_seed': 'LINESeedKR',\n"),
])
edit(ss, [
    ('설정: 글꼴 이름 (한글)',
     "      'pretendard': '프리텐다드',\n",
     "      'pretendard': '프리텐다드',\n"
     "      'line_seed': '라인 시드',\n"),
])

# 라디오 목록 방송 이름 → 라인 시드 (굵기 숫자가 달라도 찾게)
rsrc, rcrlf = load(rk)
pat = re.compile(
    r"(                      station\.name,\n)"
    r"                      // 도현체는 너무 진해서 앱 글꼴 중간 굵기로 \(곡 목록 제목과 같게\)\n"
    r"                      style: TextStyle\(\n"
    r"                        color: isPlaying \? primaryColor : baseColor,\n"
    r"                        fontSize: [0-9.]+,\n"
    r"                        fontWeight: FontWeight\.w[0-9]00,\n"
    r"                        letterSpacing: -?[0-9.]+,\n"
    r"                      \),\n")
m = pat.findall(rsrc)
if len(m) != 1:
    print('❌ 라디오: 목록 방송 이름 (찾은 개수 %d)' % len(m)); ok = False
else:
    rsrc = pat.sub(lambda mm: mm.group(1) +
        "                      // 라디오 목록 방송 이름은 라인 시드 (또렷하고 깔끔하게)\n"
        "                      style: TextStyle(\n"
        "                        fontFamily: 'LINESeedKR',\n"
        "                        color: isPlaying ? primaryColor : baseColor,\n"
        "                        fontSize: 16,\n"
        "                        fontWeight: FontWeight.w400,\n"
        "                        letterSpacing: -0.2,\n"
        "                      ),\n", rsrc)
    writes[rk] = (rsrc, rcrlf)
    print('✔ 라디오: 목록 방송 이름을 라인 시드로')

if not ok:
    print('\n하나라도 못 찾아서 아무것도 저장 안 했어요'); sys.exit(1)

os.makedirs(os.path.join('assets', 'fonts'), exist_ok=True)
z = zipfile.ZipFile(io.BytesIO(base64.b64decode(FONTS)))
lic = os.path.join('assets', 'fonts', 'FONT_LICENSES.txt')
for n in z.namelist():
    data = z.read(n)
    if n.endswith('.txt'):
        old = open(lic, encoding='utf-8').read() if os.path.isfile(lic) else ''
        if 'LINE Seed' not in old:
            open(lic, 'a', encoding='utf-8').write(data.decode('utf-8'))
        continue
    open(os.path.join('assets', 'fonts', n), 'wb').write(data)
print('✔ 글꼴 파일 2개 넣기 (assets/fonts)')

BK = os.path.join('..', 'paransori_backup_fonts_line')
for p, (text, c) in writes.items():
    bp = os.path.join(BK, p)
    os.makedirs(os.path.dirname(bp), exist_ok=True)
    shutil.copyfile(p, bp)
    open(p, 'wb').write((text.replace('\n', '\r\n') if c else text).encode('utf-8'))
print('\n저장했어요 (백업: ../paransori_backup_fonts_line) — flutter pub get 후 flutter run')
